import numpy as np
import pandas as pd
from datetime import datetime, date, timedelta
import calendar

def get_nth_weekday(year, month, weekday, n=1):
    # weekday: 0=Mon, 6=Sun
    first_day = date(year, month, 1)
    first_wday = first_day.weekday()
    offset = (weekday - first_wday + 7) % 7
    target_day = 1 + offset + (n - 1) * 7
    return date(year, month, target_day)

def get_last_weekday(year, month, weekday):
    last_day_num = calendar.monthrange(year, month)[1]
    last_day = date(year, month, last_day_num)
    offset = (last_day.weekday() - weekday + 7) % 7
    return last_day - timedelta(days=offset)

def get_good_friday(y):
    # Computes Good Friday (Easter - 2 days)
    # Using a robust algorithm for Gregorian Easter
    a = y % 19
    b = y // 100
    c = y % 100
    d = (19 * a + b) % 30
    e = (2 * (b // 4) - (b % 4) - (8 * b + 13) // 25 + 19 * a + 15) % 30
    # This is tricky, using the standard Meeus/Butcher algorithm
    a = y % 19
    b = y // 100
    c = y % 100
    d = (19 * a + b) % 30
    e = (2 * (b // 4) - (b % 4) - ((8 * b + 13) // 25) + 19 * a + 15) % 30
    # Simplified reliable way via pandas/datetime:
    # Easter date calculation
    a = y % 19
    b = y // 100
    c = y % 100
    d = (19 * a + b) % 30
    e = (2 * (b // 4) - (b % 4) - ((8 * b + 13) // 25) + 19 * a + 15) % 30
    f = (2 * (b // 4) - (b % 4) - ((8 * b + 13) // 25) + 19 * a + 15) % 7 # Still tricky
    # Let's use a known Python library approach for Easter
    from dateutil.easter import easter
    return easter(y) - timedelta(days=2)

def USNewYearsDay(y): return date(y, 1, 1)
def USIndependenceDay(y): return date(y, 7, 4)
def USThanksgivingDay(y): return get_nth_weekday(y, 11, 3, 4)
def USChristmasDay(y): return date(y, 12, 25)
def USLaborDay(y): return get_nth_weekday(y, 9, 0, 1)
def USLincolnsBirthday(y): return date(y, 2, 12)
def USColumbusDay(y): return get_nth_weekday(y, 10, 0, 2)
def USVeteransDay(y): return date(y, 11, 11)
def USElectionDay(y): return get_nth_weekday(y, 11, 1, 1)
def USWashingtonsBirthday(y): return date(y, 2, 22)
def USDecorationMemorialDay(y): return get_last_weekday(y, 5, 0)
def USPresidentsDay(y): return get_nth_weekday(y, 2, 0, 3)
def USMemorialDay(y): return get_last_weekday(y, 5, 0)
def USMLKingsBirthday(y): return get_nth_weekday(y, 1, 0, 3)
def USJuneteenthNationalIndependenceDay(y): return date(y, 6, 19)

nyse_special_closings = np.array([])

def r_holidayNYSE(year=None, type="", *args, **kwargs):
    if year is None:
        # Mocking getRmetricsOptions("currentYear")
        year = [datetime.now().year]

    year_arr = np.atleast_1d(year).astype(int)
    valid_types = ["", "standard", "special"]
    if type not in valid_types:
        type = ""

    ans_dates = []
    if type == "" or type == "standard":
        for y in year_arr:
            hols = []
            if y >= 1885: hols.extend([USNewYearsDay(y), USIndependenceDay(y), USThanksgivingDay(y), USChristmasDay(y)])
            if y >= 1887: hols.append(USLaborDay(y))
            if y not in [1898, 1906, 1907]: hols.append(get_good_friday(y))
            if 1896 <= y <= 1953: hols.append(USLincolnsBirthday(y))
            if 1909 <= y <= 1953: hols.append(USColumbusDay(y))
            if y == 1918 or y == 1921 or (1934 <= y <= 1953): hols.append(USVeteransDay(y))
            if y <= 1968 or y in [1972, 1976, 1980]: hols.append(USElectionDay(y))
            if y <= 1970: hols.extend([USWashingtonsBirthday(y), USDecorationMemorialDay(y)])
            else: hols.extend([USPresidentsDay(y), USMemorialDay(y)])
            if y >= 1998: hols.append(USMLKingsBirthday(y))
            if y >= 2022: hols.append(USJuneteenthNationalIndependenceDay(y))
            ans_dates.extend(hols)

        # The R code does `ans <- timeDate(format(holidays), zone = "NewYork", FinCenter = "NewYork")`
        # Then it shifts Sundays to Mondays.
        observed = []
        # Sort all collected holidays first
        sorted_hols = sorted(list(set(ans_dates)))
        for d in sorted_hols:
            if d.weekday() == 6: # Sunday
                observed.append(d + timedelta(days=1))
            else:
                observed.append(d)

        # July 4th Sat -> Friday rule (since 1959)
        final_observed = []
        for d in observed:
            if d >= date(1959, 7, 3) and d.weekday() == 5:
                # If the original date was July 4 and it's Saturday, move to Friday
                # we need to check if this date actually corresponds to the July 4th holiday
                # but the R logic is simpler: if the *observed* date is Sat and it's July 4th, move back.
                # Actually, NYSE rule is: if July 4 is Sat, observed on July 3. If July 4 is Sun, observed on July 5.
                if d.month == 7 and d.day == 4:
                    final_observed.append(d - timedelta(days=1))
                else:
                    final_observed.append(d)
            else:
                final_observed.append(d)

        ans_dates = sorted(list(set(final_observed)))

    if type == "" or type == "special":
        sp = []
        if nyse_special_closings.size > 0:
            for s in nyse_special_closings:
                if s.year in year_arr:
                    sp.append(date(s.year, s.month, s.day))
        ans_dates = sorted(list(set(ans_dates + sp)))

    # Final filter: remove weekends
    final = [d for d in ans_dates if d.weekday() != 5 and d.weekday() != 6]

    # Return as pandas Timestamps. To match the "T05:00:00" (EST) or "T04:00:00" (EDT)
    # seen in R's output, we must treat the date as a local New York date and 
    # convert it to UTC. 
    res = []
    for d in final:
        # Create a Timestamp for midnight in NY, then localize to NY, then convert to UTC
        # This matches the R `timeDate` behavior where the internal value is UTC.
        ts = pd.Timestamp(d).tz_localize('America/New_York').tz_convert('UTC')
        res.append(ts)

    return np.array(res)
